use axum::Router;
use axum::routing::{delete, get, patch, post, put};
use sqlx::sqlite::SqlitePoolOptions;

mod handlers;
mod models;

#[tokio::main]
async fn main() {
    let pool = SqlitePoolOptions::new()
        .connect("sqlite://app.db?mode=rwc")
        .await
        .expect("failed to connect to database");

    sqlx::query(r#"CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT,
    is_done BOOLEAN,
    due_date TEXT,
    price REAL,
    item_count INTEGER,
    notes TEXT
)"#).execute(&pool).await.expect("failed to create table");
    sqlx::query(r#"CREATE TABLE IF NOT EXISTS order_items (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    quantity INTEGER,
    unit_price REAL,
    active BOOLEAN
)"#).execute(&pool).await.expect("failed to create table");

    let app = Router::new()

        .with_state(pool);

    let listener = tokio::net::TcpListener::bind("127.0.0.1:8080").await.unwrap();
    axum::serve(listener, app).await.unwrap();
}
